#!/bin/sh
# Generated by seaworthy: acme-console, deb, after removal. See seaworthy::scripts.
# The package's only unit is its update helper's, acme-console-update.service: the logged-in
# session starts it, never these scripts.
set -e
systemd_running() { [ -d /run/systemd/system ]; }
has_systemctl() { [ -z "${DPKG_ROOT:-}" ] && command -v systemctl >/dev/null 2>&1; }
try() { "$@" || echo "acme-console: warning: '$*' failed (exit $?); continuing" >&2; }
action=none
case "${1:-}" in
  remove|purge) action=remove ;;
  abort-install) action=restore ;;
esac
if [ "$action" = remove ] && has_systemctl && systemd_running; then
  try systemctl daemon-reload
fi
